import os
import openai
import json

def extract_json(text: str, schema: dict) -> dict:
    openai.api_key = os.getenv("OPENAI_API_KEY")
    openai.api_base = os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")

    client = openai.OpenAI(
        api_key=openai.api_key,
        base_url=openai.api_base,
    )

    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {"role": "system", "content": "You are a helpful assistant that extracts information into JSON format. The user will provide a text and a JSON schema. Your task is to extract the information from the text according to the schema."},
            {"role": "user", "content": f"Extract information from the following text into JSON format according to the provided schema. Text: {text}\nSchema: {json.dumps(schema)}"}
        ],
        response_format={ "type": "json_object" }
    )
    return json.loads(response.choices[0].message.content)

import os
import openai
from typing import Iterator

def stream_completion(prompt: str) -> Iterator[str]:
    openai.api_key = os.getenv("OPENAI_API_KEY")
    openai.api_base = os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")

    client = openai.OpenAI(
        api_key=openai.api_key,
        base_url=openai.api_base,
    )

    stream = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {"role": "user", "content": prompt}
        ],
        stream=True
    )
    for chunk in stream:
        if chunk.choices[0].delta.content is not None:
            yield chunk.choices[0].delta.content

import os
import openai

def get_openai_client() -> openai.OpenAI:
    api_key = os.getenv("OPENAI_API_KEY")
    api_base = os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")

    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable not set.")

    return openai.OpenAI(
        api_key=api_key,
        base_url=api_base,
    )

from typing import List, Dict, Any
from dataclasses import dataclass

@dataclass
class ChatMessage:
    role: str
    content: str

@dataclass
class CompletionRequest:
    model: str
    messages: List[ChatMessage]
    temperature: float = 0.7
    max_tokens: int = 150

@dataclass
class CompletionResponse:
    id: str
    object: str
    created: int
    model: str
    choices: List[Dict[str, Any]]

@dataclass
class EmbeddingRequest:
    model: str
    input: str | List[str]

@dataclass
class EmbeddingResponse:
    object: str
    data: List[Dict[str, Any]]
    model: str
    usage: Dict[str, int]
